function queryFundContractById(n,t,i,r){$.ajax({async:!1,url:"/WeixinService/business/queryFundContractDetail.xhtml",data:{fundId:n,status:"Y",period:r},dataType:"json",cache:!1,type:"POST",error:function(){errorRemark("网络繁忙，请稍后再试。")},success:function(n){if(n.returnCode=="0000")if(n.fundContractDto!=null){var r=n.fundContractDto.templateCont2;r=r.replace("#amount#",t);r=r.replace("#capitalAmount#",i);$("#dd1").html(n.fundContractDto.templateCont1);$("#title2").html(n.fundContractDto.templateTitle2);$("#dd2").html(r);$("#title3").html(n.fundContractDto.templateTitle3);$("#dd3").html(n.fundContractDto.templateCont3);$("#title4").html(n.fundContractDto.templateTitle4);$("#dd4").html(n.fundContractDto.templateCont4)}else errorRemark("合同加载失败，请稍后再试"),toBack();else errorRemark("合同加载失败，请稍后再试"),toBack()}})}function showAndHide(n){$("#"+n).toggle();$(".xy_content dd").not("#"+n).hide();toTop();myScroll.refresh()}function toTop(){return myScroll.scrollTo(0,0,0),myScroll.refresh(),!0}var myScroll;$(document).ready(function(){var n,i;$(".header .top-a h2").html("产品合同");document.title="产品合同";myScroll=new IScroll("#wrapper",{scrollbars:!0,mouseWheel:!0,interactiveScrollbars:!0,shrinkScrollbars:"scale",fadeScrollbars:!0});var r=getUrlParameter("templet"),u=getUrlParameter("period"),t=getUrlParameter("money");if(isNaN(t)){errorRemark("购买金额格式有误，请返回购买页修改");return}if(n=toUpperCase(numDiv(t,1e4)),i="",n=="errorMoney"||n=="moneyMax"){errorRemark("购买金额格式有误，请返回购买页修改");return}i=n.replace("元整","");queryFundContractById(r,t/1e4,i,u);myScroll.refresh();getUserRequest("fund-contract")});document.addEventListener("touchmove",function(n){n.preventDefault()},!1)